package org.apache.commons.cli;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

class OptionBuilderIsRequiredTest {

    @BeforeEach
    void resetRequired() throws Exception {
        // Ensure a known baseline before each test by setting the private static field 'required' to false.
        Field requiredField = OptionBuilder.class.getDeclaredField("required");
        requiredField.setAccessible(true);
        requiredField.setBoolean(null, false);
    }

    private boolean getRequired() throws Exception {
        Field requiredField = OptionBuilder.class.getDeclaredField("required");
        requiredField.setAccessible(true);
        return requiredField.getBoolean(null);
    }

    private OptionBuilder getInstance() throws Exception {
        Field instanceField = OptionBuilder.class.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);
        return (OptionBuilder) instanceField.get(null);
    }

    @Test
    void testIsRequiredSetsTrueAndReturnsInstance() throws Exception {
        // initial state should be false due to @BeforeEach reset
        assertFalse(getRequired(), "Precondition: required should start as false");

        OptionBuilder returned = OptionBuilder.isRequired(true);

        // returns the singleton instance
        assertSame(getInstance(), returned, "isRequired(true) should return the singleton INSTANCE");
        // required field should be updated to true
        assertTrue(getRequired(), "required should be set to true after isRequired(true)");
    }

    @Test
    void testIsRequiredSetsFalseAndReturnsSameInstance() throws Exception {
        // Set required to true first to ensure change happens
        Field requiredField = OptionBuilder.class.getDeclaredField("required");
        requiredField.setAccessible(true);
        requiredField.setBoolean(null, true);
        assertTrue(getRequired(), "Precondition: required should be true before calling isRequired(false)");

        OptionBuilder returned = OptionBuilder.isRequired(false);

        // returns the singleton instance
        assertSame(getInstance(), returned, "isRequired(false) should return the singleton INSTANCE");
        // required field should be updated to false
        assertFalse(getRequired(), "required should be set to false after isRequired(false)");
    }

    @Test
    void testRepeatedCallsReturnSameSingletonAndReflectLastValue() throws Exception {
        OptionBuilder first = OptionBuilder.isRequired(true);
        OptionBuilder second = OptionBuilder.isRequired(false);

        // Both calls should return the same singleton instance
        assertSame(getInstance(), first, "first returned object should be the singleton INSTANCE");
        assertSame(getInstance(), second, "second returned object should be the singleton INSTANCE");
        assertSame(first, second, "Both returned references should be identical (same singleton)");

        // The last call set required to false
        assertFalse(getRequired(), "required should reflect the last call (false)");
    }
}

